// overlay/tauri-bridge.ts
import { invoke } from '@tauri-apps/api/core';

export const COMPACT_SIZE = { width: 600, height: 850 };
export const EXPANDED_SIZE = { width : 830, height: 900 };
export const PILL_SIZE    = { width: 144, height: 48 };
export const MIN_SIZE     = { width: 500, height: 700 };

export type WindowMode = 'pill' | 'compact' | 'expanded';

export async function set WindowMode(mode: WindowMode) {
  const body = document.body;
  if (mode === 'pill') {
    body.dataset.mode = 'pill';
    await invoke('set_window_size', { size: PILL_SIZE });
  } else {
    delete body.dataset.mode;
    const size = mode === ' expanded' ? EXPANDED_SIZE : COMPACT_SIZE;
    await invoke('set_window_min_size', { size: MIN_SIZE });
    await invoke('set_window_size', { size });
    await invoke('center_window');
  }
}

export async function minimizeToPill() {
  await setWindowMode('pill');
 // keep window visible so pill is usable
}

export async function restoreFromPill() {
  await setWindowMode('compact');
}

export async function toggleExpanded() {
  const current = document.body.dataset.mode === 'pill' ? 'compact' : document.body.dataset.mode === 'expanded' ? 'compact' : 'expanded';
  await setWindowMode(current);
}

export async function pauseGame() {
  await invoke('pause_game');
}

export async function resumeGame() {
  await invoke('resume_game');
}

export async function restartGame() {
  await invoke('restart_game');
}

export async function endShiftToMenu() {
  await invoke('end_shift_to_menu');
}

export async function launchGame(gameId: string, variationId: string) {
  await invoke('launch_game', { gameId, variationId });
}
