export const PREVIEW_RESIZE_MESSAGE = "gamepigeon:preview-resize";

/** Logical sizes the native frame and the browser preview both use. */
export const COMPACT_SIZE = { width: 600, height: 850 } as const;
export const EXPANDED_SIZE = { width: 830, height: 900 } as const;
export const PILL_SIZE = { width: 144, height: 48 } as const;
export const MIN_SIZE = { width: 500, height: 700 } as const;

export type OverlayFrame = "compact" | "expanded" | "pill";

export function overlayFrameSize(frame: OverlayFrame): { width: number; height: number } {
  if (frame === "expanded") return { width: EXPANDED_SIZE.width, height: EXPANDED_SIZE.height };
  if (frame === "pill") return { width: PILL_SIZE.width, height: PILL_SIZE.height };
  return { width: COMPACT_SIZE.width, height: COMPACT_SIZE.height };
}

/** Pill can shrink to itself; the restored floor never goes below MIN_SIZE. */
export function overlayMinSize(frame: OverlayFrame): { width: number; height: number } {
  if (frame === "pill") return { width: PILL_SIZE.width, height: PILL_SIZE.height };
  return { width: MIN_SIZE.width, height: MIN_SIZE.height };
}

/** Titlebar ↗ / ↙: compact ↔ expanded. A pill is restored first, not resized. */
export function toggleOverlayFrame(frame: OverlayFrame): OverlayFrame {
  return frame === "expanded" ? "compact" : "expanded";
}

/** Hide (`Esc` / `q` / the hide button) collapses to the handheld pill. */
export function minimizeOverlayFrame(): OverlayFrame {
  return "pill";
}

/** Clicking the pill restores the compact floor, never smaller than MIN_SIZE. */
export function restoreOverlayFrame(): OverlayFrame {
  return "compact";
}

  return { game, actions };
}

export function writeSavedGame(saved: SavedGame, storage: Storage = localStorage): SavedGame {
  const next: SavedGame = {
    ...saved,
    actions: saved.actions.slice(0, MAX_ACTIONS),
  };
  try {
    storage.setItem(STORAGE_KEY, JSON.stringify(next));
  } catch {
    // Persistence must never interrupt gameplay.
  }
  return next;
}

/** Restart throws this record away; returning to the menu does not. */
export function clearSavedGame(storage: Storage = localStorage): void {
  storage.removeItem(STORAGE_KEY);
}

export function appendSavedAction(action: string, storage: Storage = localStorage): SavedGame | null {
  const saved = loadSavedGame(storage);
  if (!saved || saved.actions.length >= MAX_ACTIONS) return saved;
  saved.actions.push(action);
  return writeSavedGame(saved, storage);
}

/**
 * A brand-new run must not reuse the seed it replaces. Only a resumed
 * launch may keep a stored seed.
 */
export function freshRunSeed(avoid?: number): number {
  let seed = (Math.random() * 0x100000000) >>> 0;
  if (avoid !== undefined && seed === avoid) seed = (seed + 1) >>> 0;
  return seed;
}

/**
 * Host-session overlay chrome, kept out of `app.ts` so pause / resume /
 * reset / restart can be unit tested without a DOM.
 *
 * `Stop` pauses a live run and offers a way back to the coding prompt.
 * The next `--show` resumes it. `SessionStart` (`gamepigeon:reset`) snaps
 * back to the menu and leaves the SavedGame exactly as it was. Restarting
 * mid-run is the one path that throws that record away.
 */

export type PausePromptChoice = "back-to-coding" | "continue" | "menu" | "how-to-play";

export interface OverlaySession {
  /** True while a playable run is on screen. */
  playing: boolean;
  /** Clock, workers, and input are held. */
  paused: boolean;
  /** The "Paused" card from the Stop hook. */
  pausePrompt: boolean;
  howToPlay: boolean;
  signOutPrompt: boolean;
}

export const INITIAL_OVERLAY_SESSION: OverlaySession = {
  playing: false,
  paused: false,
  pausePrompt: false,
  howToPlay: false,
  signOutPrompt: false,
};

export function hostPause(session: OverlaySession, autoPauseOnStop: boolean): OverlaySession {
  if (!autoPauseOnStop) return session;
  return {
    ...session,
    paused: session.playing ? true : session.paused,
    pausePrompt: true,
    howToPlay: false,
    signOutPrompt: false,
  };
}

export function hostResume(session: OverlaySession): OverlaySession {
  return { ...session, paused: false, pausePrompt: false };
}

/** Snap to the menu without discarding the SavedGame. */
export function hostReset(session: OverlaySession): OverlaySession {
  return {
    ...session,
    playing: false,
    paused: false,
    pausePrompt: false,
    howToPlay: false,
    signOutPrompt: false,
  };
}

export function beginPlaying(session: OverlaySession): OverlaySession {
  return { ...session, playing: true, paused: false, pausePrompt: false };
}

export function endShiftToMenu(session: OverlaySession): OverlaySession {
  return { ...session, playing: false, paused: false, pausePrompt: false };
}

export function applyPausePromptChoice(
  session: OverlaySession,
  choice: PausePromptChoice,
): OverlaySession {
  switch (choice) {
    case "back-to-coding":
      // Hide the card and leave for the editor; restoring the pill should
      // not dump the player back into a live tick.
      return { ...session, pausePrompt: false, paused: session.playing };
    case "continue":
      return { ...session, pausePrompt: false, paused: false };
    case "menu":
      return { ...session, playing: false, pausePrompt: false, paused: false };
    case "how-to-play":
      return { ...session, howToPlay: true };
  }
}

export function pausePromptKey(key: string): PausePromptChoice | undefined {
  if (key === "Escape" || key === "Enter") return "back-to-coding";
  if (key === "m" || key === "M") return "menu";
  return undefined;
}

/**
 * How a run stops mid-shift. Restart is the only path that throws the
 * SavedGame away; menu and a host reset leave seed + actions untouched.
 */
export type RunStopKind = "menu" | "restart" | "reset";

export function discardsSavedGame(kind: RunStopKind): boolean {
  return kind === "restart";
}

