  if (!autoPauseOnStop) return session;
  return {
    ...session,
    paused: session.playing ? true : session.paused,
    pausePrompt: true,
    howToPlay: false,
    signOutPrompt: false,
  };
}

export function hostResume(session: OverlaySession): OverlaySession {
  return { ...session, paused: false, pausePrompt: false };
}

