import { describe, expect, test } from "bun:test";
import { REGISTRY } from "../src/games/registry.js";
import {
  appendSavedAction,
  clearSavedGame,
  freshRunSeed,
  loadSavedGame,
  restoreGame,
  writeSavedGame,
  type SavedGame,
} from "./persistence.js";
import { discardsSavedGame } from "./pause-state.js";

function memoryStorage(initial: Record<string, string> = {}): Storage {
  const map = new Map(Object.entries(initial));
  return {
    getItem: (key) => map.get(key) ?? null,
    setItem: (key, value) => {
      map.set(key, String(value));
    },
    removeItem: (key) => {
      map.delete(key);
    },
    clear: () => map.clear(),
    get length() {
      return map.size;
    },
    key: (index) => [...map.keys()][index] ?? null,
  } as Storage;
}

function sample(overrides: Partial<SavedGame> = {}): SavedGame {
  const entry = REGISTRY[0]!;
  return {
    schemaVersion: 1,
    ownerId: "usr_test",
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: entry.variations[0]!.id,
    seed: 42,
    actions: [],
    ...overrides,
  };
}

describe("SavedGame persistence", () => {
  test("round-trips the single active-game slot", () => {
    const storage = memoryStorage();
    const saved = writeSavedGame(sample({ actions: ["sim_toggle", "tick"] }), storage);
    expect(loadSavedGame(storage)).toEqual(saved);
  });

  test("rejects a malformed record rather than guessing at a run", () => {
    const storage = memoryStorage({
      "gamepigeon.arcade.active-game.v1": JSON.stringify({ schemaVersion: 1, gameId: "restaurant-arena" }),
    });
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("rebuilds a run from seed plus accepted actions", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    const saved = sample({
      gameId: entry.id,
      gameVersion: entry.version,
      variationId: "dinner-rush",
      seed: 7,
      actions: ["sim_start", "tick"],
    });
    const restored = restoreGame(entry, saved);
    expect(restored).not.toBeNull();
    expect(restored!.actions).toEqual(["sim_start", "tick"]);
    expect(restored!.game.state().episode.tick).toBe(1);
  });

  test("refuses to restore across a game version change", () => {
    const entry = REGISTRY.find((item) => item.id === "restaurant-arena")!;
    expect(restoreGame(entry, sample({ gameVersion: "not-this-version" }))).toBeNull();
  });

  test("appending an action updates the stored log in place", () => {
    const storage = memoryStorage();
    writeSavedGame(sample(), storage);
    expect(appendSavedAction("sim_toggle", storage)?.actions).toEqual(["sim_toggle"]);
    expect(loadSavedGame(storage)?.actions).toEqual(["sim_toggle"]);
  });

  test("clearing the slot is how restart throws a run away", () => {
    const storage = memoryStorage();
    writeSavedGame(sample({ seed: 99, actions: ["tick"] }), storage);
    clearSavedGame(storage);
    expect(loadSavedGame(storage)).toBeNull();
  });

  test("a fresh seed is never the seed of the run it replaces", () => {
    const previous = 123456789;
    const original = Math.random;
    Math.random = () => previous / 0x100000000;
    try {
      expect(freshRunSeed(previous)).not.toBe(previous);
    } finally {
      Math.random = original;
    }
  });

  test("only restart discards the save; menu and host reset keep it", () => {
    expect(discardsSavedGame("restart")).toBe(true);
    expect(discardsSavedGame("menu")).toBe(false);
    expect(discardsSavedGame("reset")).toBe(false);
  });
});

import { describe, expect, test } from "bun:test";
import {
  COMPACT_SIZE,
  EXPANDED_SIZE,
  MIN_SIZE,
  PILL_SIZE,
  minimizeOverlayFrame,
  overlayFrameSize,
  overlayMinSize,
  restoreOverlayFrame,
  toggleOverlayFrame,
} from "./tauri-bridge.js";

describe("overlay window sizes", () => {
  test("exports the compact, expanded, pill, and restore-floor sizes the README documents", () => {
    expect(COMPACT_SIZE).toEqual({ width: 600, height: 850 });
    expect(EXPANDED_SIZE).toEqual({ width: 830, height: 900 });
    expect(PILL_SIZE).toEqual({ width: 144, height: 48 });
    expect(MIN_SIZE).toEqual({ width: 500, height: 700 });
  });

  test("the expand control toggles compact and expanded", () => {
    expect(toggleOverlayFrame("compact")).toBe("expanded");
    expect(toggleOverlayFrame("expanded")).toBe("compact");
    expect(overlayFrameSize("compact")).toEqual(COMPACT_SIZE);
    expect(overlayFrameSize("expanded")).toEqual(EXPANDED_SIZE);
  });

  test("hide collapses to the pill, and restore returns the compact floor never below MIN_SIZE", () => {
    expect(minimizeOverlayFrame()).toBe("pill");
    expect(overlayFrameSize("pill")).toEqual(PILL_SIZE);
    expect(overlayMinSize("pill")).toEqual(PILL_SIZE);

    expect(restoreOverlayFrame()).toBe("compact");
    const restored = overlayFrameSize(restoreOverlayFrame());
    expect(restored.width).toBeGreaterThanOrEqual(MIN_SIZE.width);
    expect(restored.height).toBeGreaterThanOrEqual(MIN_SIZE.height);
    expect(overlayMinSize("compact")).toEqual(MIN_SIZE);
  });
});

import { describe, expect, test } from "bun:test";
import {
  INITIAL_OVERLAY_SESSION,
  applyPausePromptChoice,
  beginPlaying,
  discardsSavedGame,
  endShiftToMenu,
  hostPause,
  hostReset,
  hostResume,
  pausePromptKey,
} from "./pause-state.js";

describe("host session pause / resume / reset", () => {
  test("Stop pauses a live run and opens the return-to-coding card", () => {
    const playing = beginPlaying(INITIAL_OVERLAY_SESSION);
    const paused = hostPause(playing, true);
    expect(paused.playing).toBe(true);
    expect(paused.paused).toBe(true);
    expect(paused.pausePrompt).toBe(true);
  });

  test("auto-pause off leaves the run alone", () => {
    const playing = beginPlaying(INITIAL_OVERLAY_SESSION);
    expect(hostPause(playing, false)).toEqual(playing);
  });

  test("the next show resumes play and dismisses the card", () => {
    const paused = hostPause(beginPlaying(INITIAL_OVERLAY_SESSION), true);
    const resumed = hostResume(paused);
    expect(resumed.paused).toBe(false);
    expect(resumed.pausePrompt).toBe(false);
    expect(resumed.playing).toBe(true);
  });

  test("SessionStart snaps back to the menu without discarding the save", () => {
    const paused = hostPause(beginPlaying(INITIAL_OVERLAY_SESSION), true);
    const reset = hostReset(paused);
    expect(reset.playing).toBe(false);
    expect(reset.paused).toBe(false);
    expect(reset.pausePrompt).toBe(false);
    expect(discardsSavedGame("reset")).toBe(false);
  });

  test("ending a shift to the menu also keeps the save", () => {
    expect(endShiftToMenu(beginPlaying(INITIAL_OVERLAY_SESSION)).playing).toBe(false);
    expect(discardsSavedGame("menu")).toBe(false);
  });
});

describe("paused overlay choices", () => {
  test("Esc and Enter go back to coding; M returns to the menu", () => {
    expect(pausePromptKey("Escape")).toBe("back-to-coding");
    expect(pausePromptKey("Enter")).toBe("back-to-coding");
    expect(pausePromptKey("m")).toBe("menu");
    expect(pausePromptKey("x")).toBeUndefined();
  });

  test("back to coding holds the run; continue unpauses; menu ends the shift", () => {
    const paused = hostPause(beginPlaying(INITIAL_OVERLAY_SESSION), true);
    expect(applyPausePromptChoice(paused, "back-to-coding")).toMatchObject({
      pausePrompt: false,
      paused: true,
      playing: true,
    });
    expect(applyPausePromptChoice(paused, "continue")).toMatchObject({
      pausePrompt: false,
      paused: false,
      playing: true,
    });
    expect(applyPausePromptChoice(paused, "menu")).toMatchObject({
      playing: false,
      pausePrompt: false,
    });
    expect(applyPausePromptChoice(paused, "how-to-play").howToPlay).toBe(true);
  });
});

