arguments.new_string:
function saveSetting(key: string, value: unknown): void {
  if (!(key in settings)) return;
  (settings as unknown as Record<string, unknown>)[key] = value;
  localStorage.setItem("gamepigeon.settings.productAnalytics", String(settings.productAnalytics));
  void invoke("write_settings", { settings: { [key]: value } }).catch(() => undefined);
  if (key === "defaultWindowSize" && (value === "compact" || value === "expanded") && !minimized) {
    expanded = value === "expanded";
    void applyOverlayFrame();
  }
  if (screen === "settings") drawSettings();
}

function currentFrame(): OverlayFrame {
  if (minimized) return "pill";
  return expanded ? "expanded" : "compact";
}

function updateResizeButton(): void {
  const button = document.querySelector<HTMLButtonElement>("#resize");
  if (!button) return;
  const isExpanded = currentFrame() === "expanded";
  button.textContent = isExpanded ? "↙" : "↗";
  button.setAttribute("aria-label", isExpanded ? "Compact overlay" : "Expand overlay");
}

async function applyOverlayFrame(frame: OverlayFrame = currentFrame()): Promise<void> {
  minimized = frame === "pill";
  if (frame === "compact") expanded = false;
  if (frame === "expanded") expanded = true;
  if (minimized) document.body.dataset.mode = "pill";
  else delete document.body.dataset.mode;
  updateResizeButton();
  const size = overlayFrameSize(frame);
  const min = overlayMinSize(frame);
  await windowHandle.setMinSize(overlayLogicalSize(min.width, min.height));
  await windowHandle.setSize(overlayLogicalSize(size.width, size.height));
  if (frame !== "pill") await windowHandle.center();
}

function toggleResize(): void {
  if (minimized) {
    void applyOverlayFrame(restoreOverlayFrame());
    return;
  }
  void applyOverlayFrame(toggleOverlayFrame(currentFrame()));
}

function minimizeToPill(): void {
  closeHowToPlay();
  closeSignOutPrompt();
  overlaySession = { ...overlaySession, pausePrompt: false };
  syncPausePrompt();
  void applyOverlayFrame(minimizeOverlayFrame());
}

function restoreFromPill(): void {
  if (!minimized) return;
  void applyOverlayFrame(restoreOverlayFrame());
}

function dialogElement(id: string): HTMLElement | null {
  return document.querySelector<HTMLElement>(`#${id}`);
}

function setDialogHidden(id: string, hidden: boolean): void {
  const element = dialogElement(id);
  if (element) element.hidden = hidden;
}

function howToPlayOpen(): boolean {
  return dialogElement("how-to-play")?.hidden === false;
}

function signOutPromptOpen(): boolean {
  return dialogElement("signout-prompt")?.hidden === false;
}

function pausePromptOpen(): boolean {
  return dialogElement("return-prompt")?.hidden === false;
}

function openHowToPlay(): void {
  overlaySession = { ...overlaySession, howToPlay: true };
  setDialogHidden("how-to-play", false);
}

function closeHowToPlay(): void {
  overlaySession = { ...overlaySession, howToPlay: false };
  setDialogHidden("how-to-play", true);
}

function openSignOutPrompt(): void {
  overlaySession = { ...overlaySession, signOutPrompt: true };
  setDialogHidden("signout-prompt", false);
}

function closeSignOutPrompt(): void {
  overlaySession = { ...overlaySession, signOutPrompt: false };
  setDialogHidden("signout-prompt", true);
}

function syncPausePrompt(): void {
  setDialogHidden("return-prompt", !overlaySession.pausePrompt);
}

function ownerId(): string {
  return signedInUser()?.id ?? "";
}

function activeVariationId(): string {
  return entry?.variations[variationCursor]?.id ?? savedGame?.variationId ?? "classic";
}

function variationOrDefault(selected: GameEntry, variationId?: string | null): string {
  if (variationId && selected.variations.some((variation) => variation.id === variationId)) return variationId;
  return selected.variations[0]?.id ?? "classic";
}

function persistActiveRun(): void {
  if (!entry || !game) return;
  savedGame = writeSavedGame({
    schemaVersion: 1,
    ownerId: ownerId(),
    gameId: entry.id,
    gameVersion: entry.version,
    variationId: activeVariationId(),
    seed: runSeed,
    actions: [...runActions],
  });
}

function clearTickTimer(): void {
  if (tickTimer !== undefined) window.clearTimeout(tickTimer);
  tickTimer = undefined;
}

function gameplayHeld(): boolean {
  return overlaySession.paused || minimized;
}

function syncScheduler(): void {
  clearTickTimer();
  if (screen !== "game" || !game || game.isOver() || gameplayHeld()) {
    workerOrchestrator?.pause();
    return;
  }
  const running = Boolean(arenaView(game).sim?.running);
  if (running && workerModel) {
    if (!workerOrchestrator) attachWorkerOrchestrator(game);
    workerOrchestrator?.start();
  } else {
    workerOrchestrator?.pause();
  }
  const ms = game.tickMs?.() ?? 0;
  if (ms > 0 && (!workerOrchestrator || workerOrchestrator.isPaused() || !workerModel)) {
    tickTimer = window.setTimeout(() => {
      performAction("tick");
    }, ms);
  }
}

function leaveBoard(): void {
  clearTickTimer();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  overlaySession = sessionEndShift(overlaySession);
}

function showMenu(): void {
  cursor = -1;
  screen = "menu";
  drawMenu();
}

function returnToMenu(): void {
  // Leave the SavedGame exactly as it was so the same run can resume later.
  leaveBoard();
  showMenu();
}

function launchById(gameId: string, variationId?: string | null): void {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return;
  entry = selected;
  const variation = variationOrDefault(selected, variationId);
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === variation));
  startRun(selected, variation);
}

function resumeSaved(): void {
  const saved = savedGame;
  if (!saved) return;
  const selected = MENU_GAMES.find((item) => item.id === saved.gameId);
  if (!selected || !isPlayable(selected)) return;
