    if (!workerOrchestrator) attachWorkerOrchestrator(game);
    workerOrchestrator?.start();
  } else {
    workerOrchestrator?.pause();
  }
  const ms = game.tickMs?.() ?? 0;
  if (ms > 0 && (!workerOrchestrator || workerOrchestrator.isPaused() || !workerModel)) {
    tickTimer = window.setTimeout(() => {
      performAction("tick");
    }, ms);
  }
}

function leaveBoard(): void {
  clearTickTimer();
  stopWorkerOrchestrator();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;
  game = undefined;
  overlaySession = sessionEndShift(overlaySession);
}

function showMenu(): void {
  cursor = -1;
  screen = "menu";
  drawMenu();
}

function returnToMenu(): void {
  // Leave the SavedGame exactly as it was so the same run can resume later.
  leaveBoard();
  showMenu();
}

function launchById(gameId: string, variationId?: string | null): void {
  const selected = findGame(gameId);
  if (!selected || !isPlayable(selected)) return;
  entry = selected;
  const variation = variationOrDefault(selected, variationId);
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === variation));
  startRun(selected, variation);
}

function resumeSaved(): void {
  const saved = savedGame;
  if (!saved) return;
  const selected = MENU_GAMES.find((item) => item.id === saved.gameId);
  if (!selected || !isPlayable(selected)) return;
  const restored = restoreGame(selected, saved);
  if (!restored) {
    startRun(selected, saved.variationId);
    return;
  }
  entry = selected;
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === saved.variationId));
  beginActiveRun(selected, saved.variationId, restored.game, saved.seed, restored.actions);
}

function startRun(selected: GameEntry, variationId: string, avoidSeed?: number): void {
  if (!selected.create) return;
  if (activeTrace && !gameEnded) sealRun("user_quit");
  const seed = freshRunSeed(avoidSeed);
  const active = selected.create(variationId);
  active.reset(seed);
  beginActiveRun(selected, variationId, active, seed, []);
}

function restartRun(): void {
  if (!entry) return;
  const selected = entry;
  const variationId = activeVariationId();
  const avoid = runSeed;
  if (activeTrace && !gameEnded) sealRun("restart");
  if (discardsSavedGame("restart")) {
    clearSavedGame();
    savedGame = undefined;
  }
  gameEnded = false;
  startRun(selected, variationId, avoid);
}

function beginActiveRun(
  selected: GameEntry,
  variationId: string,
  active: PlayableGame,
  seed: number,
  actions: string[],
): void {
  stopWorkerOrchestrator();
  cancelTraceFlush();
  restaurantArenaScene?.destroy();
  restaurantArenaScene = undefined;

  entry = selected;
  variationCursor = Math.max(0, selected.variations.findIndex((item) => item.id === variationId));
  game = active;
  runSeed = seed;
  runActions = [...actions];
  gameEnded = false;
  gameStartedAt = Date.now();
  actionsTaken = actions.length;
  replaying = false;
  overlaySession = beginPlaying(overlaySession);
  persistActiveRun();

  if (settings.recordingWhilePlaying) {
    activeTrace = createOverlayTrace(selected, variationId, seed, gameStartedAt);
    sessionReceiptId = activeTrace.gameId;
    persistTrace(activeTrace);
  } else {
    activeTrace = undefined;
    sessionReceiptId = crypto.randomUUID();
  }
  gameSessionId = sessionReceiptId;

  screen = "game";
  captureOverlayEvent("game.started", { game_type: selected.id, variation_id: variationId }, gameSessionId);
  renderGameScreen();
  syncScheduler();
}

function sealRun(reason: EpisodeEndReason): void {
  if (!game || !entry || gameEnded) return;
  clearTickTimer();
  stopWorkerOrchestrator();
  const completed = reason === "game_over" || reason === "won" || reason === "lost";
  const score = game.score();
  lastReplay = {
    entry,
    variationId: activeVariationId(),
    seed: runSeed,
    actions: [...runActions],
    ...(game.name === "restaurant-arena"
      ? { arenaTrace: captureArenaTrace(game as unknown as RestaurantGame, { runKind: "live", ...(sessionReceiptId ? { sessionId: sessionReceiptId } : {}) }) }
      : {}),
  };
  if (activeTrace) {
    submitTrace(activeTrace, reason, completed ? score : undefined);
    activeTrace = undefined;
  }
  captureOverlayEvent("game.ended", {
    game_type: entry.id,
    variation_id: activeVariationId(),
    outcome: completed ? "completed" : "abandoned",
    score,
    success: game.hasWon(),
    duration_ms: Math.max(0, Date.now() - gameStartedAt),
    actions_taken: actionsTaken,
  }, gameSessionId);
  if (completed) {
    void invoke("append_local_score", {
      score: {
        gameId: gameSessionId ?? `game_${crypto.randomUUID()}`,
        gameType: entry.id,
        variationId: activeVariationId(),
        score,
        success: game.hasWon(),
        completedAt: new Date().toISOString(),
        durationMs: Math.max(0, Date.now() - gameStartedAt),
        platform: "overlay",
      },
    }).then(() => refreshLocalScores()).catch(() => undefined);
  }
  gameEnded = true;
}

function gameOverMarkup(): string {
  if (!game) return "";
  const won = game.hasWon();
  const title = won ? "Service complete" : "Shift over";
  const tone = won ? "win" : "loss";
  const arena = game.name === "restaurant-arena";
  return `<div class="game-end-overlay" data-tone="${tone}">
    <div class="game-end-content${arena ? " arena-end-content" : ""}">
      <h2 class="game-end-title">${escapeHtml(title)}</h2>
      ${getArenaDebriefHtml()}
      ${getArenaEvidenceHtml()}
      ${sessionReceiptHtml()}
      ${getArenaTimelineHtml()}
      <div class="game-end-actions">
        <button type="button" class="primary" data-restart>Play again</button>
        ${arena ? `<div class="export-trace-group">
          <button type="button" class="export-trace-btn" data-action="export-trace">Export Trace</button>
          <button type="button" class="export-trace-btn-alt" data-action="export-trace-jsonl">JSONL</button>
        </div>` : ""}
        <button type="button" data-menu>Menu</button>
      </div>
    </div>
  </div>`;
}

function paintGameOver(): void {
  if (!game || !game.isOver()) return;
  const board = screenElement.querySelector<HTMLElement>(".board") ?? screenElement.querySelector<HTMLElement>(".game");
  if (!board || board.querySelector(".game-end-overlay")) return;
  board.insertAdjacentHTML("beforeend", gameOverMarkup());
}

function applyHostPause(): void {
  overlaySession = hostPause(overlaySession, settings.autoPauseOnStop);
  closeHowToPlay();
  closeSignOutPrompt();
  syncPausePrompt();
  if (overlaySession.paused) {
    workerOrchestrator?.pause();
    clearTickTimer();
  }
