}

function applyHostResume(): void {
  overlaySession = hostResume(overlaySession);
  syncPausePrompt();
  if (minimized) void applyOverlayFrame(restoreOverlayFrame());
  syncScheduler();
}

function applyHostReset(): void {
  overlaySession = hostReset(overlaySession);
  closeHowToPlay();
  closeSignOutPrompt();
  syncPausePrompt();
  if (screen === "game") {
    leaveBoard();
    showMenu();
  }
}

function applyPauseChoice(choice: ReturnType<typeof pausePromptKey>): void {
  if (!choice) return;
  overlaySession = applyPausePromptChoice(overlaySession, choice);
  if (choice === "how-to-play") openHowToPlay();
