  void invoke("shutdown");
});
document.querySelector("#pill")?.addEventListener("click", () => restoreFromPill());
document.querySelector("#pill")?.addEventListener("mousedown", (event) => {
  if ((event as MouseEvent).button !== 0) return;
  void windowHandle.startDragging();
});
document.querySelector(".titlebar")?.addEventListener("mousedown", (event) => {
  const target = event.target as HTMLElement | null;
  if (target?.closest("button")) return;
  void windowHandle.startDragging();
});
