document.querySelector("#continue-game")?.addEventListener("click", () => applyPauseChoice("continue"));
document.querySelector("#return-menu")?.addEventListener("click", () => applyPauseChoice("menu"));
document.querySelector("#signout-confirm")?.addEventListener("click", () => void confirmSignOut());
document.querySelector("#signout-cancel")?.addEventListener("click", () => closeSignOutPrompt());

window.addEventListener("gamepigeon:launch", (event) => {
  const detail = (event as CustomEvent<{ game?: string; variation?: string }>).detail;
  if (detail?.game) launchById(detail.game, detail.variation);
});
window.addEventListener("gamepigeon:pause", () => applyHostPause());
window.addEventListener("gamepigeon:resume", () => applyHostResume());
window.addEventListener("gamepigeon:reset", () => applyHostReset());
